/* Minimal freestanding libc for the JavaScript MIPS VM. */
#include <stddef.h>
#include <stdint.h>
#include <stdarg.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <sys/types.h>

/* ------------------------------------------------------------------ */
/* raw syscalls (VM ABI: number in $v0, args in $a0-$a2, result $v0) */
/* ------------------------------------------------------------------ */
static long msc(long n, long a, long b, long c)
{
    register long v0 __asm__("$2") = n;
    register long a0 __asm__("$4") = a;
    register long a1 __asm__("$5") = b;
    register long a2 __asm__("$6") = c;
    __asm__ volatile("syscall"
                     : "+r"(v0)
                     : "r"(a0), "r"(a1), "r"(a2)
                     : "memory");
    return v0;
}
#define SYS_read 0
#define SYS_write 1
#define SYS_open 2
#define SYS_close 3
#define SYS_lseek 8

/* Values expected by vm.js, not the host Linux values. */
#define V_O_RDONLY 0
#define V_O_WRONLY 1
#define V_O_RDWR 2
#define V_O_CREAT 64
#define V_O_TRUNC 512
#define V_O_APPEND 1024

static int sys_open(const char *p, int fl, int mode) { return (int)msc(SYS_open, (long)p, fl, mode); }
static int sys_close(int fd) { return (int)msc(SYS_close, fd, 0, 0); }
static long sys_read(int fd, void *b, long n) { return msc(SYS_read, fd, (long)b, n); }
static long sys_write(int fd, const void *b, long n) { return msc(SYS_write, fd, (long)b, n); }
static long sys_lseek(int fd, long off, int wh) { return msc(SYS_lseek, fd, off, wh); }

/* ------------------------------------------------------------------ */
/* errno / ctype                                                       */
/* ------------------------------------------------------------------ */
static int the_errno;
int *__errno_location(void) { return &the_errno; }

static int toupper_tab[384];
