{
    if (!toupper_ready) {
        int i;
        for (i = 0; i < 384; i++) {
            int c = i - 128;
            toupper_tab[i] = (c >= 'a' && c <= 'z') ? c - 32 : c;
        }
        toupper_ready = 1;
    }
    return toupper_tab;
}

/* ------------------------------------------------------------------ */
/* memory                                                              */
/* ------------------------------------------------------------------ */
extern unsigned char __heap_start[];
static unsigned char *heap_top = __heap_start;

typedef struct blk {
    size_t size;
    int free;
    struct blk *next;
} blk;

static blk *freelist;

void *malloc(size_t n)
{
    blk *b, *best = 0;
    size_t need = (n + 7) & ~(size_t)7;
    if (need == 0) need = 8;

    for (b = freelist; b; b = b->next) {
        if (b->free && b->size >= need) {
            best = b;
            break;
        }
    }
    if (best) {
        if (best->size >= need + sizeof(blk) + 16) {
            blk *nb = (blk *)((unsigned char *)(best + 1) + need);
            nb->size = best->size - need - sizeof(blk);
            nb->free = 1;
            nb->next = freelist;
            freelist = nb;
            best->size = need;
        }
        best->free = 0;
        return best + 1;
    }

    b = (blk *)heap_top;
    heap_top += sizeof(blk) + need;
    b->size = need;
    b->free = 0;
    b->next = freelist;
    freelist = b;
    return b + 1;
}

void free(void *p)
{
    blk *b;
    if (!p) return;
    b = ((blk *)p) - 1;
    b->free = 1;
}

void *calloc(size_t nm, size_t sz)
{
    size_t n = nm * sz;
