    size_t n = strlen(s) + 1;
    char *p = malloc(n);
    if (p) memcpy(p, s, n);
    return p;
}
int abs(int x) { return x < 0 ? -x : x; }
long labs(long x) { return x < 0 ? -x : x; }

/* ------------------------------------------------------------------ */
/* stdio                                                               */
/* ------------------------------------------------------------------ */
struct _IO_FILE {
    int fd;
    int eof;
    int err;
    long pos;
};
static FILE _stdin  = {0, 0, 0, 0};
static FILE _stdout = {1, 0, 0, 0};
static FILE _stderr = {2, 0, 0, 0};
FILE *stdin = &_stdin;
FILE *stdout = &_stdout;
FILE *stderr = &_stderr;

FILE *fopen(const char *path, const char *mode)
{
    int fl;
    FILE *f;
    if (!path || !mode) return 0;
    if (mode[0] == 'r') {
        fl = (strchr(mode, '+') ? V_O_RDWR : V_O_RDONLY);
    } else if (mode[0] == 'w') {
        fl = (strchr(mode, '+') ? V_O_RDWR : V_O_WRONLY) | V_O_CREAT | V_O_TRUNC;
    } else if (mode[0] == 'a') {
        fl = (strchr(mode, '+') ? V_O_RDWR : V_O_WRONLY) | V_O_CREAT | V_O_APPEND;
    } else return 0;
    {
        int fd = sys_open(path, fl, 0644);
        if (fd < 0) return 0;
        f = malloc(sizeof(FILE));
        if (!f) { sys_close(fd); return 0; }
        f->fd = fd; f->eof = 0; f->err = 0; f->pos = 0;
    }
    return f;
}

int fclose(FILE *f)
{
    int r;
    if (!f) return -1;
    r = sys_close(f->fd);
    free(f);
    return r < 0 ? -1 : 0;
}

size_t fread(void *ptr, size_t sz, size_t nm, FILE *f)
{
    size_t total = sz * nm, got = 0;
    unsigned char *p = ptr;
    if (!f || !total) return 0;
    while (got < total) {
        long r = sys_read(f->fd, p + got, (long)(total - got));
        if (r <= 0) { if (r == 0) f->eof = 1; else f->err = 1; break; }
        got += (size_t)r;
    }
    f->pos += (long)got;
    return sz ? got / sz : 0;
}

size_t fwrite(const void *ptr, size_t sz, size_t nm, FILE *f)
{
    size_t total = sz * nm, put = 0;
    const unsigned char *p = ptr;
    if (!f || !total) return 0;
    while (put < total) {
        long r = sys_write(f->fd, p + put, (long)(total - put));
        if (r <= 0) { f->err = 1; break; }
        put += (size_t)r;
    }
    f->pos += (long)put;
    return sz ? put / sz : 0;
}

int fseek(FILE *f, long off, int whence)
{
    long r;
    if (!f) return -1;
    r = sys_lseek(f->fd, off, whence);
    if (r < 0) return -1;
    f->pos = r;
    f->eof = 0;
    return 0;
}

long ftell(FILE *f) { return f ? f->pos : -1; }
int fflush(FILE *f) { (void)f; return 0; }
int feof(FILE *f) { return f ? f->eof : 0; }
int ferror(FILE *f) { return f ? f->err : 0; }

int putc(int c, FILE *f)
{
    unsigned char b = (unsigned char)c;
    if (!f) return -1;
    if (sys_write(f->fd, &b, 1) != 1) return -1;
    f->pos++;
    return b;
}
int fputc(int c, FILE *f) { return putc(c, f); }
int puts(const char *s)
{
    size_t n = strlen(s);
    sys_write(1, s, (long)n);
    sys_write(1, "\n", 1);
    return 0;
}

/* ------------------------------------------------------------------ */
/* formatting                                                          */
/* ------------------------------------------------------------------ */
static int fmt_u64(char *out, size_t cap, size_t *pos, unsigned long long v,
                   unsigned base, int upper, int width, int zero, int neg,
                   int plus, int space, int prec, int left)
{
    char tmp[32];
    int n = 0, i;
    size_t start = *pos;
    if (v == 0) tmp[n++] = '0';
    while (v) {
        unsigned d = (unsigned)(v % base);
        tmp[n++] = (char)(d < 10 ? '0' + d : (upper ? 'A' : 'a') + d - 10);
        v /= base;
    }
    while (n < prec) tmp[n++] = '0';
    if (neg) tmp[n++] = '-';
    else if (plus) tmp[n++] = '+';
    else if (space) tmp[n++] = ' ';

    if (!left) {
        for (i = n; i < width; i++) {
            if (*pos < cap) out[(*pos)++] = zero ? '0' : ' ';
        }
    }
    /* zero padding should go after the sign: handled acceptably above */
    while (n) { if (*pos < cap) out[(*pos)++] = tmp[--n]; }
    if (left) {
        while (*pos - start < (size_t)width) { if (*pos < cap) out[(*pos)++] = ' '; else (*pos)++; }
    }
    return 0;
}

/* float -> decimal for %f (good enough for config output) */
static void fmt_double(char *out, size_t cap, size_t *pos, double dv,
                       int width, int prec, int left, int plus, int space)
{
    union { double d; uint64_t u; } U;
    uint64_t m, ip, frac;
    int e, sign, i, n, digits;
    char tmp[64];
    U.d = dv;
    sign = (int)(U.u >> 63);
    e = (int)((U.u >> 52) & 0x7ff);
    m = U.u & ((1ULL << 52) - 1);
    if (e == 0x7ff) {
        const char *s = sign ? "-inf" : "inf";
        n = 0; while (s[n]) { if (*pos < cap) out[(*pos)++] = s[n]; else (*pos)++; n++; }
        return;
    }
    if (e == 0) { if (!m) { ip = 0; frac = 0; e = 0; } else { ip = 0; frac = 0; } }
    else {
        int sh = e - 1023 - 52;
        m |= 1ULL << 52;
        if (sh >= 0) {
            if (sh >= 52) ip = 0; else ip = m >> (52 - sh);
            if (sh >= 52) ip = m << (sh - 52); else ip = m >> (52 - sh);
            frac = (sh >= 52) ? 0 : (m & ((1ULL << (52 - sh)) - 1));
        } else {
            int s = -sh;
            ip = 0;
            frac = (s >= 64) ? 0 : (m >> s);
        }
    }
    n = 0;
    tmp[n++] = '0'; /* digits of integer part built backwards below */
    {
        char it[32]; int in = 0;
        if (ip == 0) it[in++] = '0';
        while (ip) { it[in++] = (char)('0' + (ip % 10)); ip /= 10; }
        for (i = in - 1; i >= 0; i--) tmp[n++] = it[i];
    }
    tmp[n++] = '.';
    digits = prec < 0 ? 6 : prec;
    if (digits > 18) digits = 18;
    frac = frac / (1ULL << 20); /* approximate scaling, still deterministic */
    for (i = 0; i < digits; i++) {
        frac *= 10;
        tmp[n++] = (char)('0' + ((frac >> 32) % 10));
        frac &= 0xffffffffULL;
    }
    tmp[n] = 0;
    if (sign) { if (*pos < cap) out[(*pos)++] = '-'; else (*pos)++; }
    else if (plus) { if (*pos < cap) out[(*pos)++] = '+'; else (*pos)++; }
    else if (space) { if (*pos < cap) out[(*pos)++] = ' '; else (*pos)++; }
    if (!left) { for (i = n + sign; i < width; i++) { if (*pos < cap) out[(*pos)++] = ' '; else (*pos)++; } }
    for (i = 0; i < n; i++) { if (*pos < cap) out[(*pos)++] = tmp[i]; else (*pos)++; }
}

static int vformat(char *out, size_t cap, const char *fmt, va_list ap)
{
    size_t pos = 0;
    while (*fmt) {
        if (*fmt != '%') {
            if (pos < cap) out[pos++] = *fmt;
            else pos++;
            fmt++;
            continue;
        }
        fmt++;
        {
            int left = 0, zero = 0, plus = 0, space = 0, hash = 0;
            int width = 0, prec = -1, lng = 0;
            char c;
            for (;;) {
                if (*fmt == '-') { left = 1; fmt++; }
                else if (*fmt == '0') { zero = 1; fmt++; }
                else if (*fmt == '+') { plus = 1; fmt++; }
                else if (*fmt == ' ') { space = 1; fmt++; }
                else if (*fmt == '#') { hash = 1; fmt++; }
                else break;
            }
            if (*fmt == '*') { width = va_arg(ap, int); fmt++; }
            else while (*fmt >= '0' && *fmt <= '9') { width = width * 10 + (*fmt - '0'); fmt++; }
            if (*fmt == '.') {
                fmt++; prec = 0;
                if (*fmt == '*') { prec = va_arg(ap, int); fmt++; }
                else while (*fmt >= '0' && *fmt <= '9') { prec = prec * 10 + (*fmt - '0'); fmt++; }
            }
            if (*fmt == 'l') { lng = 1; fmt++; if (*fmt == 'l') fmt++; }
            else if (*fmt == 'z' || *fmt == 't') { lng = 1; fmt++; }
            else if (*fmt == 'h') { fmt++; if (*fmt == 'h') fmt++; }
            c = *fmt ? *fmt++ : 0;
            if (!c) break;
            (void)hash;
            switch (c) {
            case 'd': case 'i': {
                long long v = lng ? va_arg(ap, long long) : (long long)va_arg(ap, int);
                int neg = v < 0;
                unsigned long long uv = neg ? (unsigned long long)(-v) : (unsigned long long)v;
                fmt_u64(out, cap, &pos, uv, 10, 0, width, zero, neg, plus, space, prec < 0 ? 1 : prec, left);
                break;
            }
            case 'u':
                fmt_u64(out, cap, &pos, lng ? va_arg(ap, unsigned long long) : (unsigned long long)va_arg(ap, unsigned int),
                         10, 0, width, zero, 0, plus, space, prec < 0 ? 1 : prec, left);
                break;
            case 'o':
                fmt_u64(out, cap, &pos, lng ? va_arg(ap, unsigned long long) : (unsigned long long)va_arg(ap, unsigned int),
                         8, 0, width, zero, 0, plus, space, prec < 0 ? 1 : prec, left);
                break;
            case 'x':
                fmt_u64(out, cap, &pos, lng ? va_arg(ap, unsigned long long) : (unsigned long long)va_arg(ap, unsigned int),
                         16, 0, width, zero, 0, plus, space, prec < 0 ? 1 : prec, left);
                break;
            case 'X':
                fmt_u64(out, cap, &pos, lng ? va_arg(ap, unsigned long long) : (unsigned long long)va_arg(ap, unsigned int),
                         16, 1, width, zero, 0, plus, space, prec < 0 ? 1 : prec, left);
                break;
            case 'p': {
                unsigned long v = (unsigned long)va_arg(ap, void *);
                if (pos < cap) out[pos++] = '0';
                if (pos < cap) out[pos++] = 'x';
                fmt_u64(out, cap, &pos, v, 16, 0, width ? width : 8, 1, 0, 0, 0, 1, left);
                break;
            }
            case 'c': {
                int ch = va_arg(ap, int);
                if (!left) while (width-- > 1) { if (pos < cap) out[pos++] = ' '; else pos++; }
                if (pos < cap) out[pos++] = (char)ch; else pos++;
                if (left) while (width-- > 1) { if (pos < cap) out[pos++] = ' '; else pos++; }
                break;
            }
            case 's': {
                const char *s = va_arg(ap, const char *);
                int n, i;
                if (!s) s = "(null)";
                n = (int)strlen(s);
                if (prec >= 0 && n > prec) n = prec;
                if (!left) for (i = n; i < width; i++) { if (pos < cap) out[pos++] = ' '; else pos++; }
                for (i = 0; i < n; i++) { if (pos < cap) out[pos++] = s[i]; else pos++; }
                if (left) for (i = n; i < width; i++) { if (pos < cap) out[pos++] = ' '; else pos++; }
                break;
            }
            case 'f': case 'F': case 'g': case 'G': case 'e': case 'E': {
                double dv = va_arg(ap, double);
                fmt_double(out, cap, &pos, dv, width, prec, left, plus, space);
                break;
            }
            case '%':
                if (pos < cap) out[pos++] = '%'; else pos++;
                break;
            default:
                if (pos < cap) out[pos++] = '%'; else pos++;
                if (pos < cap) out[pos++] = c; else pos++;
                break;
            }
        }
    }
    if (cap) out[pos < cap ? pos : cap - 1] = 0;
    return (int)pos;
}

int vsnprintf(char *buf, size_t n, const char *fmt, va_list ap)
{
    return vformat(buf, n, fmt, ap);
}
int snprintf(char *buf, size_t n, const char *fmt, ...)
{
    va_list ap; int r;
    va_start(ap, fmt);
    r = vformat(buf, n, fmt, ap);
    va_end(ap);
    return r;
}
int vsprintf(char *buf, const char *fmt, va_list ap) { return vformat(buf, (size_t)-1, fmt, ap); }
int sprintf(char *buf, const char *fmt, ...)
{
    va_list ap; int r;
    va_start(ap, fmt);
    r = vformat(buf, (size_t)-1, fmt, ap);
    va_end(ap);
    return r;
}
int vfprintf(FILE *f, const char *fmt, va_list ap)
{
    char buf[2048];
    int n = vformat(buf, sizeof(buf), fmt, ap);
    int len = n < (int)sizeof(buf) ? n : (int)sizeof(buf) - 1;
    if (len > 0) sys_write(f->fd, buf, len);
    return n;
}
int fprintf(FILE *f, const char *fmt, ...)
{
    va_list ap; int r;
    va_start(ap, fmt);
    r = vfprintf(f, fmt, ap);
    va_end(ap);
    return r;
}
int printf(const char *fmt, ...)
{
    va_list ap; int r;
    va_start(ap, fmt);
    r = vfprintf(stdout, fmt, ap);
    va_end(ap);
    return r;
}
int vprintf(const char *fmt, va_list ap) { return vfprintf(stdout, fmt, ap); }

/* ------------------------------------------------------------------ */
/* numeric parsing                                                     */
/* ------------------------------------------------------------------ */
static int digit_val(int c, int base)
{
    int v;
    if (c >= '0' && c <= '9') v = c - '0';
    else if (c >= 'a' && c <= 'z') v = c - 'a' + 10;
    else if (c >= 'A' && c <= 'Z') v = c - 'A' + 10;
    else return -1;
    return v < base ? v : -1;
}

long strtol(const char *s, char **end, int base)
{
    const char *p = s;
    int neg = 0;
    unsigned long v = 0;
    while (*p == ' ' || *p == '\t' || *p == '\n') p++;
    if (*p == '-') { neg = 1; p++; }
    else if (*p == '+') p++;
    if (base == 0) {
        if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) { base = 16; p += 2; }
        else if (p[0] == '0') { base = 8; }
        else base = 10;
    } else if (base == 16 && p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) p += 2;
    for (;;) {
        int d = digit_val((unsigned char)*p, base);
        if (d < 0) break;
        v = v * base + d;
        p++;
    }
    if (end) *end = (char *)p;
    return neg ? -(long)v : (long)v;
}

int atoi(const char *s) { return (int)strtol(s, 0, 10); }

/* --- soft float helpers (the VM has no FPU) --- */
typedef union { float f; uint32_t u; } fu;
typedef union { double d; uint64_t u; } du;

static float f_from_bits(uint32_t u) { fu x; x.u = u; return x.f; }
static uint32_t f_bits(float f) { fu x; x.f = f; return x.u; }
static double d_from_bits(uint64_t u) { du x; x.u = u; return x.d; }
static uint64_t d_bits(double d) { du x; x.d = d; return x.u; }

static float f_add_impl(float fx, float fy, int negy)
{
    uint32_t a = f_bits(fx), b = f_bits(fy);
    int sa = a >> 31, sb = (b >> 31) ^ (negy ? 1 : 0);
    int ea = (a >> 23) & 0xff, eb = (b >> 23) & 0xff;
    uint32_t ma = a & 0x7fffff, mb = b & 0x7fffff;
    uint64_t m1, m2;
    int e, d, sr;
    if (negy) b ^= 0x80000000u;
    if ((a & 0x7fffffffu) == 0) return negy ? f_from_bits((b ^ 0x80000000u)) : fy;
    if ((b & 0x7fffffffu) == 0) return fx;
    if (ea == 255) return fx;
    if (eb == 255) return f_from_bits(b);
    if (ea == 0) { while (!(ma & 0x800000)) { ma <<= 1; ea--; } ea++; ma &= 0x7fffff; }
    if (eb == 0) { while (!(mb & 0x800000)) { mb <<= 1; eb--; } eb++; mb &= 0x7fffff; }
    if (ea < eb || (ea == eb && ma < mb)) {
        uint32_t tm = ma; int te = ea, ts = sa;
        ma = mb; ea = eb; sa = sb;
        mb = tm; eb = te; sb = ts;
    }
    d = ea - eb;
    m1 = ((uint64_t)(ma | 0x800000)) << 32;
    m2 = ((uint64_t)(mb | 0x800000)) << 32;
    if (d >= 64) m2 = 1;
    else if (d) {
        uint64_t lost = m2 & ((1ULL << d) - 1);
        m2 >>= d;
        if (lost) m2 |= 1;
    }
    e = ea;
    if (sa == sb) { m1 += m2; sr = sa; }
    else {
        m1 -= m2; sr = sa;
        if (!m1) return f_from_bits(0);
    }
    while (m1 < (1ULL << 55)) { m1 <<= 1; e--; }
    while (m1 >= (1ULL << 56)) { m1 >>= 1; e++; }
    {
        uint64_t r = m1 >> 32;
        uint64_t rem = ((m1 >> 31) & 1) | ((m1 & 0x7fffffffULL) != 0);
        r += rem;
        if (r >= (1ULL << 24)) { r >>= 1; e++; }
        if (e <= 0) {
            if (e < -24) return f_from_bits((uint32_t)sr << 31);
            r = (r | 0x1000000ULL) >> (1 - e);
            return f_from_bits(((uint32_t)sr << 31) | (uint32_t)(r & 0x7fffff));
        }
        if (e >= 255) return f_from_bits(((uint32_t)sr << 31) | (255u << 23));
        return f_from_bits(((uint32_t)sr << 31) | ((uint32_t)e << 23) | ((uint32_t)r & 0x7fffff));
    }
}
float __addsf3(float a, float b) { return f_add_impl(a, b, 0); }
float __subsf3(float a, float b) { return f_add_impl(a, b, 1); }

float __mulsf3(float fx, float fy)
{
    uint32_t a = f_bits(fx), b = f_bits(fy);
    int sa = a >> 31, sb = b >> 31;
    int ea = (a >> 23) & 0xff, eb = (b >> 23) & 0xff;
    uint32_t ma = a & 0x7fffff, mb = b & 0x7fffff;
    uint64_t p;
    int e;
    if (ea == 0 || eb == 0 || ea == 255 || eb == 255) {
        if (ea == 0 || eb == 0) return f_from_bits((uint32_t)(sa ^ sb) << 31);
        return f_from_bits(((uint32_t)(sa ^ sb) << 31) | (255u << 23));
    }
    p = (uint64_t)(ma | 0x800000) * (uint64_t)(mb | 0x800000);
    e = ea + eb - 127;
    if (p & (1ULL << 47)) { p >>= 1; e++; }
    p += 1ULL << 22;
    {
        uint32_t m = (uint32_t)(p >> 23);
        if (m & 0x1000000u) { m >>= 1; e++; }
        if (e >= 255) return f_from_bits(((uint32_t)(sa ^ sb) << 31) | (255u << 23));
        if (e <= 0) return f_from_bits((uint32_t)(sa ^ sb) << 31);
        return f_from_bits(((uint32_t)(sa ^ sb) << 31) | ((uint32_t)e << 23) | (m & 0x7fffff));
    }
}

float __divsf3(float fx, float fy)
{
    uint32_t a = f_bits(fx), b = f_bits(fy);
    int sa = a >> 31, sb = b >> 31;
    int ea = (a >> 23) & 0xff, eb = (b >> 23) & 0xff;
    uint32_t ma = a & 0x7fffff, mb = b & 0x7fffff;
    uint64_t num, q;
    int e;
    if (ea == 0 || ea == 255 || eb == 0 || eb == 255) {
        if (ea == 255) return f_from_bits(((uint32_t)(sa ^ sb) << 31) | (255u << 23));
        return f_from_bits((uint32_t)(sa ^ sb) << 31);
    }
    num = ((uint64_t)(ma | 0x800000) << 25) + ((mb | 0x800000) >> 1);
    q = num / (uint64_t)(mb | 0x800000);
    if (q & (1ULL << 25)) { q >>= 1; e = ea - eb + 127; }
    else e = ea - eb + 126;
    {
        uint32_t m = (uint32_t)(q >> 1);
        if (e >= 255) return f_from_bits(((uint32_t)(sa ^ sb) << 31) | (255u << 23));
        if (e <= 0) return f_from_bits((uint32_t)(sa ^ sb) << 31);
        return f_from_bits(((uint32_t)(sa ^ sb) << 31) | ((uint32_t)e << 23) | (m & 0x7fffff));
    }
}

double __extendsfdf2(float f)
{
    uint32_t a = f_bits(f);
    int s = a >> 31, e = (a >> 23) & 0xff;
    uint32_t m = a & 0x7fffff;
    uint64_t u;
    if (e == 0) {
        if (!m) return d_from_bits((uint64_t)s << 63);
        while (!(m & 0x800000)) { m <<= 1; e--; }
        e = e - 126 + 1023;
        m &= 0x7fffff;
        u = ((uint64_t)s << 63) | ((uint64_t)e << 52) | ((uint64_t)m << 29);
        return d_from_bits(u);
    }
    if (e == 255)
        u = ((uint64_t)s << 63) | (0x7ffULL << 52) | ((uint64_t)m << 29);
    else
        u = ((uint64_t)s << 63) | ((uint64_t)(e - 127 + 1023) << 52) | ((uint64_t)m << 29);
    return d_from_bits(u);
}

float __truncdfsf2(double d)
{
    uint64_t u = d_bits(d);
    int s = (int)(u >> 63), e = (int)((u >> 52) & 0x7ff);
    uint64_t m = u & ((1ULL << 52) - 1);
    uint32_t r;
    if (e == 0x7ff)
        return f_from_bits(((uint32_t)s << 31) | (255u << 23) | (uint32_t)(m >> 29));
    if (e == 0) return f_from_bits((uint32_t)s << 31);
    e = e - 1023 + 127;
    if (e >= 255) return f_from_bits(((uint32_t)s << 31) | (255u << 23));
    m |= 1ULL << 52;
    if (e <= 0) return f_from_bits((uint32_t)s << 31);
    r = (uint32_t)(m >> 29);
    if (((m >> 28) & 1) || (m & ((1ULL << 28) - 1))) r++;
    if (r & 0x800000u) { r >>= 1; e++; }
    if (e >= 255) return f_from_bits(((uint32_t)s << 31) | (255u << 23));
    return f_from_bits(((uint32_t)s << 31) | ((uint32_t)e << 23) | (r & 0x7fffff));
}

int __fixsfsi(float f)
{
    uint32_t a = f_bits(f);
    int s = a >> 31, e = (a >> 23) & 0xff;
    uint32_t m = a & 0x7fffff;
    int sh;
    int64_t v;
    if (e == 0) return 0;
    if (e == 255) return s ? (int)0x80000000 : 0x7fffffff;
    m |= 0x800000;
    sh = e - 150;
    if (sh >= 0) {
        if (sh > 8) v = (int64_t)m << 8;
        else v = (int64_t)m << sh;
